from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Normalize each pair: u = min(a,b) + 1 (smallest allowed left endpoint contribution),
        # v = max(a,b) (pair becomes active once r >= v).
        m = len(conflictingPairs)
        buckets = [[] for _ in range(n + 1)]
        us = [0] * m
        for i, (a, b) in enumerate(conflictingPairs):
            if a < b:
                u, v = a + 1, b
            else:
                u, v = b + 1, a
            us[i] = u
            buckets[v].append(i)

        base = 0
        gain = [0] * m
        max1 = 0          # current maximum u (0 means no constraint, L = 1)
        max2 = 0          # current second distinct u
        cnt1 = 0          # number of active pairs achieving max1
        idx1 = -1         # index of the pair achieving max1 (valid when cnt1 == 1)

        for r in range(1, n + 1):
            for i in buckets[r]:
                u = us[i]
                if u > max1:
                    max2 = max1
                    max1 = u
                    cnt1 = 1
                    idx1 = i
                elif u == max1:
                    cnt1 += 1
                elif u > max2:
                    max2 = u
            # With all pairs active, smallest allowed left endpoint is max1 (since u = min+1,
            # and max1 == 0 corresponds to L = 1).
            base += r - max1 + 1
            # If exactly one pair attains the max, removing it relaxes L from max1 to max2.
            if cnt1 == 1:
                gain[idx1] += max1 - max2

        return base + max(gain)

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    parent = list(range(N + 1))
    xr = [0] * (N + 1)   # xor from node to its parent
    rank = [0] * (N + 1)
    touched = [False] * (N + 1)

    def find(x):
        # returns (root, xor from x to root), with path compression
        if parent[x] == x:
            return x, 0
        root = x
        acc = 0
        while parent[root] != root:
            acc ^= xr[root]
            root = parent[root]
        # compress: node originally had xor cur to old parent chain start;
        # after compression, xr[node] = xor from node to root = acc ^ (xor from x to node)
        node = x
        cur = 0
        while parent[node] != root:
            nxt = parent[node]
            nxr = xr[node]
            parent[node] = root
            xr[node] = acc ^ cur
            cur ^= nxr
            node = nxt
        return root, acc

    ok = True
    for _ in range(M):
        x = int(next(it)); y = int(next(it)); z = int(next(it))
        touched[x] = True
        touched[y] = True
        if not ok:
            continue
        if x == y:
            if z != 0:
                ok = False
            continue
        rx, mx = find(x)
        ry, my = find(y)
        if rx == ry:
            if (mx ^ my) != z:
                ok = False
        else:
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
                mx, my = my, mx
            parent[ry] = rx
            xr[ry] = mx ^ my ^ z
            if rank[rx] == rank[ry]:
                rank[rx] += 1

    if not ok:
        sys.stdout.write("-1\n")
        return

    # group touched vertices by root
    groups = {}
    for v in range(1, N + 1):
        if not touched[v]:
            continue
        r, m = find(v)
        if r in groups:
            groups[r].append((v, m))
        else:
            groups[r] = [(v, m)]

    A = [0] * (N + 1)
    B = 30  # Z <= 1e9 < 2^30
    for r, members in groups.items():
        s = len(members)
        cnt = [0] * B
        for v, m in members:
            mm = m
            while mm:
                lb = mm & (-mm)
                b = lb.bit_length() - 1
                cnt[b] += 1
                mm ^= lb
        rval = 0
        for b in range(B):
            c = cnt[b]
            if s - c < c:
                rval |= (1 << b)
        for v, m in members:
            A[v] = m ^ rval

    out = ' '.join(str(A[i]) for i in range(1, N + 1))
    sys.stdout.write(out + "\n")

