    rows_W = {}
    for _ in range(M):
        x = int(data[idx]); y = int(data[idx+1]); c = data[idx+2]; idx += 3
        if c == b'B':
            rows_B.setdefault(x, []).append(y)
        else:
            if x in rows_W:
                if y < rows_W[x]:
                    rows_W[x] = y
            else:
                rows_W[x] = y

    # Sweep rows in increasing order, maintaining the minimum W-y seen so far
    # (over all rows <= current). For each B at (x, y) we need y < minW_sofar,
    # where minW includes W cells in the same row (x2 == x1 allowed).
    events = set(rows_B) | set(rows_W)
    INF = N + 1
    minW = INF
    ok = True
    for x in sorted(events):
        # W cells in this row also constrain B cells in this same row (x2 <= x1).
        if x in rows_W and rows_W[x] < minW:
            minW = rows_W[x]
        if x in rows_B:
            for y in rows_B[x]:
                if y >= minW:
                    ok = False
                    break
        if not ok:
            break

    sys.stdout.write("Yes\n" if ok else "No\n")

main()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def feasible(L: int) -> bool:
            if L == 1:
                # Final string must be perfectly alternating.
                # Count mismatches against both alternating targets.
                mism0 = 0  # target pattern starting with '0': "0101..."
                for i, ch in enumerate(s):
                    expected = '0' if i % 2 == 0 else '1'
                    if ch != expected:
                        mism0 += 1
                mism1 = n - mism0  # mismatches to the opposite pattern "1010..."
                return min(mism0, mism1) <= numOps
            # L >= 2: handle each maximal run independently.
            flips = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                m = j - i
                # Place flips every (L+1) positions inside the run.
                flips += m // (L + 1)
                if flips > numOps:
                    return False
                i = j
            return flips <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

import sys
from bisect import bisect_right
from collections import defaultdict

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    x = int(data[idx]); idx += 1
    y = int(data[idx]); idx += 1

    houses = []
    for _ in range(N):
        hx = int(data[idx]); idx += 1
        hy = int(data[idx]); idx += 1
        houses.append((hx, hy))

    row_intervals = defaultdict(list)  # y -> list of (x1, x2)
    col_intervals = defaultdict(list)  # x -> list of (y1, y2)

    for _ in range(M):
        d = data[idx].decode(); idx += 1
        c = int(data[idx]); idx += 1
        if d == 'U':
            col_intervals[x].append((y, y + c))
            y += c
        elif d == 'D':
            col_intervals[x].append((y - c, y))
            y -= c
        elif d == 'L':
            row_intervals[y].append((x - c, x))
            x -= c
        else:  # 'R'
            row_intervals[y].append((x, x + c))
            x += c

    # Merge intervals per key; store sorted starts and ends arrays.
    def merge(intervals):
        intervals.sort()
        starts = []
        ends = []
        for a, b in intervals:
            if starts and a <= ends[-1] + 1:
                if b > ends[-1]:
                    ends[-1] = b
            else:
                starts.append(a)
                ends.append(b)
        return starts, ends

    row_merged = {}
    for k, v in row_intervals.items():
        row_merged[k] = merge(v)
    col_merged = {}
    for k, v in col_intervals.items():
        col_merged[k] = merge(v)

    def covered(starts, ends, p):
        # is p inside any merged interval?
        i = bisect_right(starts, p) - 1
        return i >= 0 and ends[i] >= p

    count = 0
    for hx, hy in houses:
        hit = False
        rm = row_merged.get(hy)
        if rm is not None and covered(rm[0], rm[1], hx):
            hit = True
        if not hit:
            cm = col_merged.get(hx)
            if cm is not None and covered(cm[0], cm[1], hy):
                hit = True
        if hit:
            count += 1

    sys.stdout.write(f"{x} {y} {count}\n")

main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # Map value -> index for values that can possibly have an edge (value <= threshold)
        idx_of = {}
        for i, v in enumerate(nums):
            if v <= threshold:
                idx_of[v] = i

        # For each possible gcd d, connect the smallest present multiple s of d
        # with every other present multiple m where lcm(s, m) = s*m/d <= threshold.
        for d in range(1, threshold + 1):
            s = -1  # smallest present multiple of d
            for m in range(d, threshold + 1, d):
                if m in idx_of:
                    if s == -1:
                        s = m
                    else:
                        # lcm(s, m) = s*m/d (exact since d divides both)
                        if s * m // d <= threshold:
                            union(idx_of[s], idx_of[m])
                        else:
                            # m increases, so s*m/d only grows; safe to stop
                            break

        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)
